def largest_v1(numbers):
    biggest = 0
    for n in numbers:
        if n > biggest:
            biggest = n
    return biggest

def largest_v2(numbers):
    biggest = numbers[0]
    for n in numbers[1:]:
        if n > biggest:
            biggest = n
    return biggest

for test in ([3, 9, 4], [12, 5, 30, 8], [-4, -2, -7]):
    print(test, "v1:", largest_v1(test), " v2:", largest_v2(test))

def count_up(secret):
    guesses = 0
    for guess in range(1, 101):
        guesses += 1
        if guess == secret:
            return guesses

def halving(secret):
    low, high, guesses = 1, 100, 0
    while True:
        guesses += 1
        guess = (low + high) // 2
        if guess == secret:
            return guesses
        if guess < secret:
            low = guess + 1
        else:
            high = guess - 1

for secret in (7, 50, 73, 100):
    print(f"secret {secret:>3}: counting up {count_up(secret):>3} guesses, halving {halving(secret)} guesses")
worst_up = max(count_up(s) for s in range(1, 101))
worst_half = max(halving(s) for s in range(1, 101))
print("worst case over all 100 secrets:", worst_up, "vs", worst_half)

def gcd_by_trying(a, b):
    checks = 0
    for d in range(min(a, b), 0, -1):
        checks += 1
        if a % d == 0 and b % d == 0:
            return d, checks

def gcd_euclid(a, b):
    steps = 0
    while b != 0:
        steps += 1
        print(f"  step {steps}: {a} = {a // b} x {b} + {a % b}")
        a, b = b, a % b
    return a, steps

print("trying every number:", gcd_by_trying(1071, 462))
print("Euclid:")
print("result:", gcd_euclid(1071, 462))
